from typing import List

def mergeIntervalsWithNames(intervals: List[List[str]]) -> List[str]:
    events = []
    for name, s, e in intervals:
        events.append((int(s), 1, name))   # 开始
        events.append((int(e), 0, name))   # 结束
    events.sort(key=lambda x: x[0])        # 同一时刻的事件互不影响输出，稳定排序即可
    active = []                            # 当前覆盖的名字，按开始先后排列
    res = []
    prev = None
    for t, is_start, name in events:
        if prev is not None and t != prev and active:
            res.append(f"{prev} {t} " + ", ".join(active))
        if is_start:
            active.append(name)
        else:
            active.remove(name)
        prev = t
    return res
